REM {Il faut utiliser une vue dans laquelle une colonne contient les UNIDs};
v_Cle := SIAi_Nom;
v_NomVue := "V_SIAi20";

@If(v_Cle = NULL; @Return(@Failure("Le nom est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; v_Cle; 2; [ReturnDocumentUniqueID]);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("L'aide est déjà définie."))

v_Cle := SICT_Nom;
v_NomVue := "V_SICT20";

@If(v_Cle = NULL; @Return(@Failure("Le nom est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; v_Cle; 1; [ReturnDocumentUniqueID]);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("Le courriel est déjà défini."))

