v_Merlin := @DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Cont_ClientNoFmt; "Merl_Icone"; [FailSilent]);
@If(v_SDS = 174 | v_Merlin = 59; @True; @False)

v_NomTable := "Cont_ContactFonctions" + @If(SF_SDS; "SDS"; "") + SF_Langue;
v_Cle := Cont_ContactFonction;

@Replace(v_Cle; @IfError(@DbLookup( ""; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup( ""; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 5); ""))

