v_Adresse1 := @ReplaceSubstring(Clie_ClientAdresse1; "." : ","; "");
v_Adresse2 := @Trim(@ReplaceSubstring(v_Adresse1; "ave " : "Ave " : "boul " : "Boul "; "Avenue " : "Avenue " : "Boulevard " : "Boulevard "));
v_Adresse := @Implode(@Trim(v_Adresse2 : Clie_ClientVille : Clie_ClientProvince : Clie_ClientCodePostal : ("(" + @Trim(Clie_ClientNom1 + " " + Clie_ClientNom2) + ")")); "+");
"http://maps.google.ca/maps?q=" + v_Adresse + "&iwloc=A&hl=fr"

REM {***** Validations de base};
@If(Cont_ClientNo1 = ""; @Return(@Success); !@Matches(Cont_ClientNo2; "{0123456789}{0123456789}{0123456789}"); @Return(@Failure("La deuxième partie du numéro de client est invalide.")); "");

v_VueSICl := "V_Clie20";
v_CleSICl := @Text(Cont_ClientNo1) + "-" + Cont_ClientNo2;

REM {***** Vérifier l'existence du document};
@If(@IsError(@DbLookup("" : "NoCache"; SF_ServeurSICl : SF_FichierSICl; v_VueSICl; v_CleSICl; 1)); @Failure("Le numéro SI Client est inexistant."); @Success)

v_Adresse1 := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Cont_ClientNoFmt; 3); "");
v_Adresse2 := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Cont_ClientNoFmt; 4); "");
v_Ville := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Cont_ClientNoFmt; 5); "");
v_Province := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Cont_ClientNoFmt; 8); "");
v_CodePostal := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Cont_ClientNoFmt; 9); "");

@If(v_Adresse2 = ""; v_Adresse1; v_Adresse1 : v_Adresse2) : (v_Ville + "  " + v_Province + "   " + v_CodePostal)

v_NomTable := "ISO3166-1" + SF_Langue;
v_Pays := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Cont_ClientNoFmt; 6); "");

@If(@IsNull(v_Pays) | v_Pays = "CA"; ""; @Replace(v_Pays; @IfError(@DbLookup( "" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup( "" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 5); "")))

v_ItemContactTitre := "Cont_ContactTitre";
v_ContactSexe := Cont_Sexe_1;

REM {Vérifier que le titre sélectionné existe dans la table};
v_NomTable := "Civilite" + @ThisValue;
v_Titres := @DbLookup("" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 4);
@If(@IsError(v_Titres); @Return(@ThisValue); @IsMember(@GetField(v_ItemContactTitre); v_Titres); @Return(@ThisValue); "");

REM {S'il n'existe pas, rechercher le premier titre disponible en fonction du sexe};
v_Sexes := @IfError(@DbLookup("" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 12); @Return(@ThisValue));
v_Titre := @Replace(v_ContactSexe; v_Sexes; v_Titres);
@SetField(v_ItemContactTitre; @If(@Elements(v_Titre) > 1; v_Titre[1]; v_Titre));
@ThisValue

v_GDK := @Subset(@DbName; 1) : "SI_GDK.nsf";
v_NomTable := "ISO639-1x" + SF_Langue;
v_Cle := Cont_ContactLangue;

@If(@IsNull(v_Cle); ""; @Replace(v_Cle; @IfError(@DbLookup(""; v_GDK; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup(""; v_GDK; "V_Tabl20"; v_NomTable; 5); "")))

REM {Extraire le sexe correspondant au titre};
v_NomTable := "Civilite" + Cont_ContactLangue;
v_ContactTitre := Cont_ContactTitre;

v_Titres := @DbLookup("" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 4);
v_Sexes := @DbLookup("" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 12);

@If(@IsNull(v_ContactTitre) | @IsError(v_Titres) | @IsError(v_Sexes); "M"; @Replace(v_ContactTitre; v_Titres; v_Sexes))
